        BigDecimal total = BigDecimal.ZERO;
        for (Map.Entry<String, List<Map<String, Object>>> group : groupByType(items).entrySet()) {
            total = total.add(basePremiumForAlikeItems(group.getKey(), group.getValue().size()));
        }
        return total;
    }

    private Map<String, List<Map<String, Object>>> groupByType(List<Map<String, Object>> items) {
        Map<String, List<Map<String, Object>>> grouped = new LinkedHashMap<>();
        for (Map<String, Object> item : items) {
